identify_affected_iso_weeks <- function(dates) unique(format(as.Date(dates),"%G-W%V"))
aggregate_daily_to_weekly <- function(daily_dir,weekly_dir,prefix="mintemp",iso_weeks=NULL,require_complete_week=TRUE,overwrite=TRUE,template_path,rebuild_all=FALSE) { inv <- inventory_grid_directory(daily_dir,prefix,"daily",FALSE); inv <- inv[inv$valid&&!inv$estimated,]; if(!nrow(inv)) return(list(written=character(),skipped=character())); if(rebuild_all||is.null(iso_weeks)) iso_weeks <- identify_affected_iso_weeks(inv$date); template <- terra::rast(template_path); fs::dir_create(weekly_dir,recurse=TRUE); written <- skipped <- character(); for(w in iso_weeks) { y <- as.integer(substr(w,1,4)); k <- as.integer(substr(w,7,8)); monday <- ISOweek::ISOweek2date(paste0(w,"-1")); ds <- seq(monday,monday+6,by="day"); rows <- inv[inv$date %in% ds,]; if(require_complete_week && length(unique(rows$date))!=7) { skipped<-c(skipped,w); next }; if(length(unique(rows$date))!=7) next; rows <- rows[match(ds,rows$date),]; if(anyNA(rows$path)) next; ras <- terra::rast(rows$path); if(any(!vapply(seq_len(terra::nlyr(ras)),function(i) validate_raster_against_template(ras[[i]],template,c(-100,70),TRUE)$valid,logical(1)))) stop("Invalid input raster for ",w); z <- terra::app(ras,min,na.rm=TRUE); out <- file.path(weekly_dir,format_weekly_filename(prefix,y,k)); if(file.exists(out)&&!overwrite) next; terra::writeRaster(z,out,overwrite=TRUE,wopt=list(datatype="FLT4S",gdal=c("COMPRESS=DEFLATE","PREDICTOR=3","TILED=YES"))); if(!validate_weekly_output(out,y,k, list(project=list(output_prefix=prefix),validation=list(minimum_celsius=-100,maximum_celsius=70,require_exact_template_geometry=TRUE)))$valid) stop("Weekly validation failed: ",w); est<-file.path(weekly_dir,format_weekly_filename(prefix,y,k,TRUE)); if(file.exists(est)) unlink(est); written<-c(written,out) }; list(written=written,skipped_incomplete=skipped) }
